mapper.delete:
delete from MST_BOND_MARKET_INFO
where SEC_ID = #{secId}
and VALUE_DATE = to_date(#{valueDate},'yyyy-MM-dd')

mapper.select:
select distinct t.FINPROD_ID id, t.FINPROD_ID text, t.FINPROD_ABBR object from FIN_PRODUCT t where t.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and t.FINPROD_ID = #{initValue}
and (lower(t.FINPROD_ID) like '%' || lower(#{search}) || '%' or lower(t.FINPROD_ABBR) like '%' || lower(#{search}) || '%' or lower(t.FINPROD_NAME) like '%' || lower(#{search}) || '%')
